<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('pos.void');$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT s.*,c.name customer_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.id=:id');$st->execute([':id'=>$id]);$sale=$st->fetch();if(!$sale||$sale['status']!=='completed'){flash('error','Only completed sales can be voided.');redirect('sales/view?id='.$id);}$errors=[];
$alloc=db()->prepare('SELECT COUNT(*) FROM customer_payment_allocations WHERE sale_id=:id');$alloc->execute([':id'=>$id]);$hasDebtPayments=(int)$alloc->fetchColumn()>0;
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$reason=trim((string)($_POST['reason']??''));if(mb_strlen($reason)<5)$errors[]='Enter a clear reason for voiding this sale.';if($hasDebtPayments)$errors[]='This sale has customer debt payments allocated to it. Reverse those payments before voiding the sale.';
if(!$errors){$pdo=db();try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT * FROM sales WHERE id=:id AND status="completed" FOR UPDATE');$lock->execute([':id'=>$id]);$fresh=$lock->fetch();if(!$fresh)throw new RuntimeException('Sale is no longer available to void.');$allocLock=$pdo->prepare('SELECT id FROM customer_payment_allocations WHERE sale_id=:id LIMIT 1 FOR UPDATE');$allocLock->execute([':id'=>$id]);if($allocLock->fetchColumn()!==false)throw new RuntimeException('This sale has customer debt payments allocated to it and cannot be voided.');$items=$pdo->prepare('SELECT si.*,p.track_stock,p.current_stock FROM sale_items si INNER JOIN products p ON p.id=si.product_id WHERE si.sale_id=:id FOR UPDATE');$items->execute([':id'=>$id]);foreach($items->fetchAll() as$i){if((int)$i['track_stock']!==1)continue;$before=quantity_to_milli($i['current_stock']);$qty=quantity_to_milli($i['quantity']);$after=$before+$qty;$up=$pdo->prepare('UPDATE products SET current_stock=:stock WHERE id=:id');$up->execute([':stock'=>milli_to_decimal($after),':id'=>(int)$i['product_id']]);$sm=$pdo->prepare('INSERT INTO stock_movements(branch_id,product_id,movement_type,reference_type,reference_id,reference_no,quantity_change,unit_cost,stock_before,stock_after,reason,created_by) VALUES(:branch,:product,"void_reversal","sale",:sale,:no,:qty,:cost,:before,:after,:reason,:user)');$sm->execute([':branch'=>(int)$fresh['branch_id'],':product'=>(int)$i['product_id'],':sale'=>$id,':no'=>$fresh['sale_no'],':qty'=>milli_to_decimal($qty),':cost'=>$i['cost_price'],':before'=>milli_to_decimal($before),':after'=>milli_to_decimal($after),':reason'=>'Sale void: '.$reason,':user'=>(int)current_user()['id']]);}
$creditStmt=$pdo->prepare('SELECT COALESCE(SUM(sp.amount),0) FROM sale_payments sp INNER JOIN payment_methods pm ON pm.id=sp.payment_method_id WHERE sp.sale_id=:id AND pm.method_type="credit"');$creditStmt->execute([':id'=>$id]);$creditCents=money_to_cents((string)$creditStmt->fetchColumn());if($creditCents>0&&$fresh['customer_id']){$customerLock=$pdo->prepare('SELECT account_balance FROM customers WHERE id=:id FOR UPDATE');$customerLock->execute([':id'=>(int)$fresh['customer_id']]);$oldBalance=money_to_cents((string)$customerLock->fetchColumn());$newBalance=max(0,$oldBalance-$creditCents);$cu=$pdo->prepare('UPDATE customers SET account_balance=:balance WHERE id=:id');$cu->execute([':balance'=>cents_to_decimal($newBalance),':id'=>(int)$fresh['customer_id']]);$ledger=$pdo->prepare('INSERT INTO customer_ledger(customer_id,entry_date,entry_type,sale_id,reference_no,description,debit_amount,credit_amount,balance_after,created_by) VALUES(:customer,NOW(),"adjustment_credit",:sale,:ref,:description,0.00,:credit,:balance,:user)');$ledger->execute([':customer'=>(int)$fresh['customer_id'],':sale'=>$id,':ref'=>$fresh['sale_no'],':description'=>'Credit reversed for voided sale',':credit'=>cents_to_decimal($creditCents),':balance'=>cents_to_decimal($newBalance),':user'=>(int)current_user()['id']]);}
$cashStmt=$pdo->prepare('SELECT COALESCE(SUM(sp.amount),0) FROM sale_payments sp INNER JOIN payment_methods pm ON pm.id=sp.payment_method_id WHERE sp.sale_id=:id AND pm.method_type="cash"');$cashStmt->execute([':id'=>$id]);$cashCents=money_to_cents((string)$cashStmt->fetchColumn());if($cashCents>0){$cm=$pdo->prepare('INSERT INTO cash_movements(cash_session_id,branch_id,movement_type,reference_type,reference_id,amount,description,created_by) VALUES(:session,:branch,"cash_out","sale_void",:sale,:amount,:description,:user)');$cm->execute([':session'=>active_cash_session_id($pdo,(int)current_user()['id'],(int)$fresh['branch_id']),':branch'=>(int)$fresh['branch_id'],':sale'=>$id,':amount'=>cents_to_decimal(-$cashCents),':description'=>'Cash reversal for voided sale '.$fresh['sale_no'],':user'=>(int)current_user()['id']]);}
$upSale=$pdo->prepare('UPDATE sales SET status="voided",voided_by=:user,voided_at=NOW(),void_reason=:reason WHERE id=:id');$upSale->execute([':user'=>(int)current_user()['id'],':reason'=>$reason,':id'=>$id]);transactional_audit($pdo,'sale_voided','sales',$id,'Sale voided: '.$fresh['sale_no'].'.',['status'=>'completed'],['status'=>'voided','reason'=>$reason]);$pdo->commit();flash('success','Sale voided and stock restored.');redirect('sales/view?id='.$id);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();error_log('Void sale failed: '.$e->getMessage());$errors[]='The sale could not be voided. No reversal was saved.';}}}
$pageTitle='Void Sale';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="narrow-page"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('sales/view?id='.$id))?>">← Sale</a><h2>Void <?=e($sale['sale_no'])?></h2><p>This reverses stock and customer credit while keeping the original transaction history.</p></div></div><?php if($hasDebtPayments):?><div class="app-alert app-alert--warning">This sale has later debt payments allocated to it and cannot be voided until those allocations are handled.</div><?php endif;?><?php foreach($errors as$er):?><div class="app-alert app-alert--danger"><?=e($er)?></div><?php endforeach;?><form method="post" class="form-card"><?=csrf_field()?><div class="form-section"><div class="danger-summary"><span>Sale total</span><strong><?=e(money($sale['total_amount']))?></strong></div><div class="field"><label>Reason for voiding</label><textarea name="reason" rows="5" required placeholder="Explain why this financial transaction is being reversed"></textarea></div></div><div class="form-actions"><a class="button button--ghost" href="<?=e(app_url('sales/view?id='.$id))?>">Cancel</a><button class="button button--danger" type="submit" <?=$hasDebtPayments?'disabled':''?>>Void sale</button></div></form></div></main></div><?php require BASE_PATH.'/includes/footer.php';?>
